const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    int n = s.size();
    int zeros = count(s.begin(), s.end(), '0');
    int ones = n - zeros;

    // dp[len][z] = number of strings of length len with z zeros
    vector<vector<int>> dp(n + 1, vector<int>(zeros + 1, 0));
    dp[n][zeros] = 1;

    for (int len = n; len > 1; --len) {
        for (int z = 0; z <= zeros; ++z) {
            int o = len - z;
            if (o < 0 || o > ones) continue;
            if (dp[len][z] == 0) continue;
            // remove a zero if possible
            if (z > 0) {
                dp[len - 1][z - 1] = (dp[len - 1][z - 1] + dp[len][z]) % MOD;
            }
            // remove a one if possible
            if (o > 0) {
                dp[len - 1][z] = (dp[len - 1][z] + dp[len][z]) % MOD;
            }
        }
    }

    int ans = 0;
    for (int len = 1; len <= n; ++len) {
        for (int z = 0; z <= zeros; ++z) {
            ans = (ans + dp[len][z]) % MOD;
        }
    }
    cout << ans << '\n';
    return 0;
}

