using namespace std;

static const long long MOD = 998244353;

// fast power
long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    cin >> S;
    int n = (int)S.size();

    int c0 = 0, c1 = 0;
    for (char ch : S) {
        if (ch == '0') c0++;
        else c1++;
    }

    // dp[a][b][t]:
    // considering a zeros and b ones remaining to be deleted in total,
    // and current first character type = t (0 or 1),
    // whether such a state is reachable.
    //
    // We only need boolean reachability.
    vector<vector<array<char,2>>> dp(c0 + 1, vector<array<char,2>>(c1 + 1, {0,0}));

    // initial state
    dp[c0][c1][S[0] - '0'] = 1;

    for (int a = c0; a >= 0; --a) {
        for (int b = c1; b >= 0; --b) {
            for (int t = 0; t < 2; ++t) {
                if (!dp[a][b][t]) continue;
                int len = a + b;
                if (len < 2) continue;

                // choose second character type u among remaining multiset after taking first=t
                for (int u = 0; u < 2; ++u) {
                    int cntu = (u == 0 ? a : b);
                    if (u == t) cntu--; // one copy is already used as first char
                    if (cntu <= 0) continue;

                    // From pair (t, u), erase one and keep the other.
                    // The kept character can be reinserted anywhere, including front,
                    // so the new first character can be:
                    // - the kept character
                    // - or any character still present after deleting one of {t,u}
                    //
                    // We can model all possibilities directly.

                    // Option 1: delete t, keep u
                    {
                        int na = a - (t == 0);
                        int nb = b - (t == 1);
                        if (na >= 0 && nb >= 0) {
                            // first can be u
                            dp[na][nb][u] = 1;
                            // or some other existing type after deletion
                            if (na > (u == 0 ? 1 : 0)) dp[na][nb][0] = 1;
                            if (nb > (u == 1 ? 1 : 0)) dp[na][nb][1] = 1;
                        }
                    }

                    // Option 2: delete u, keep t
                    {
                        int na = a - (u == 0);
                        int nb = b - (u == 1);
                        if (na >= 0 && nb >= 0) {
                            // first can be t
                            dp[na][nb][t] = 1;
                            // or some other existing type after deletion
                            if (na > (t == 0 ? 1 : 0)) dp[na][nb][0] = 1;
                            if (nb > (t == 1 ? 1 : 0)) dp[na][nb][1] = 1;
                        }
                    }
                }
            }
        }
    }

    // A binary string is determined only by its counts.
    // For each reachable remaining counts (a,b), every string with exactly a zeros and b ones is obtainable.
    // Count sum C(a+b, a) over all reachable (a,b).
    int N = n;
    vector<long long> fact(N + 1), ifact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;
    ifact[N] = modpow(fact[N], MOD - 2);
    for (int i = N; i > 0; --i) ifact[i - 1] = ifact[i] * i % MOD;

    auto C = [&](int nn, int kk) -> long long {
        if (kk < 0 || kk > nn) return 0;
        return fact[nn] * ifact[kk] % MOD * ifact[nn - kk] % MOD;
    };

    long long ans = 0;
    for (int a = 0; a <= c0; ++a) {
        for (int b = 0; b <= c1; ++b) {
            bool ok = false;
            if (a + b == 0) ok = true; // empty string can always be reached
            else {
                if (dp[a][b][0] || dp[a][b][1]) ok = true;
            }
            if (ok) {
                ans += C(a + b, a);
                if (ans >= MOD) ans -= MOD;
            }
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}

