        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        queue.add(S);
        visited.add(S);

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            if (cur.length() < 2) continue;
            char c1 = cur.charAt(0), c2 = cur.charAt(1);
            String rest = cur.substring(2);
            for (int keep = 0; keep < 2; keep++) {
                char kept = (keep == 0) ? c1 : c2;
                for (int pos = 0; pos <= rest.length(); pos++) {
                    String next = rest.substring(0, pos) + kept + rest.substring(pos);
                    if (visited.add(next)) {
                        queue.add(next);
                    }
                }
            }
        }

        System.out.println(visited.size() % MOD);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String s = fs.next();
        int n = s.length();

        int cnt0 = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') cnt0++;
        }
        int cnt1 = n - cnt0;

        // Reachable strings are determined only by:
        // - final length L >= 1
        // - counts of 0 and 1 not exceeding originals
        // - at least one of:
        //   * if L == 1: any single char that exists initially
        //   * if L >= 2: both symbols present in final string, or
        //                final string is all c and initial string had at least one c
        //
        // In fact every binary string of length L with z zeros and o ones
        // such that 0<=z<=cnt0, 0<=o<=cnt1, z+o=L, L>=1 is reachable.
        // Reason:
        // Each operation keeps exactly one of the first two chars, so after k operations
        // we keep exactly one char from each removed pair, plus the untouched suffix.
        // Since the kept char can be reinserted anywhere, order can be arranged arbitrarily.
        // Thus any multiset obtainable by choosing survivors from removed pairs and suffix
        // is achievable, and for binary strings this means any counts within original bounds
        // except length 0. For each feasible counts, every arrangement is achievable.
        //
        // Therefore answer = sum_{z=0..cnt0} sum_{o=0..cnt1, z+o>=1} C(z+o, z)

        long[][] C = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }

        long ans = 0;
        for (int z = 0; z <= cnt0; z++) {
            for (int o = 0; o <= cnt1; o++) {
                if (z + o == 0) continue;
                ans += C[z + o][z];
                if (ans >= MOD) ans -= MOD;
            }
        }

        System.out.println(ans % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}
